def set_text(paragraph, text):
    if paragraph.runs:
        base = deepcopy(paragraph.runs[0]._r.rPr)
    else:
        base = None
    paragraph._element.clear_content()
    run = paragraph.add_run(text)
    if base is not None:
        run._r.get_or_add_rPr().append(base)

def fill_table(table, rows):
    for r, values in enumerate(rows):
        for c, value in enumerate(values):
            cell = table.cell(r, c)
            # Some template diagram cells contain several paragraphs. Keep the
            # first paragraph's formatting and remove all obsolete content.
            for paragraph in cell.paragraphs[1:]:
                paragraph._element.getparent().remove(paragraph._element)
            set_text(cell.paragraphs[0], value)

